-- The locked account a posting must find, by what it is for. Not for the app to call.
CREATE FUNCTION app.control_account(p_tenant uuid, p_control text) RETURNS uuid
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_account uuid;
BEGIN
  SELECT a.id INTO v_account FROM public.accounts a WHERE a.tenant_id = p_tenant AND a.is_control AND a.control_type = p_control AND NOT a.is_group;
  IF v_account IS NULL THEN
    RAISE EXCEPTION 'the chart of accounts has no account for %', p_control USING ERRCODE = 'SE064';
  END IF;
  RETURN v_account;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.control_account(uuid, text) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.control_account(uuid, text) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: sales invoices join the sales documents ───────────────────────────────────────
-- The sales team writes invoices as it writes orders (the founder's decision: a salesperson
-- may issue an invoice). The warehouse does not, and does not read them.
DROP POLICY sales_documents_insert ON public.sales_documents;
--> statement-breakpoint
CREATE POLICY sales_documents_insert ON public.sales_documents FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND ((SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson') OR ((SELECT app.tenant_role()) = 'warehouse_manager' AND kind = 'delivery'))
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
    AND kind IN ('quotation', 'order', 'delivery', 'invoice')
    AND status = 'draft'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
-- The guard of a sales document, written out again with what an invoice adds: it is made from a
-- submitted order or a posted delivery note the writer may see; it takes an SI number and the
-- day it falls due; once posted it is never cancelled; and neither is a delivery note it has
-- billed, nor an order with goods delivered or invoiced. Everything else is as it was.
CREATE OR REPLACE FUNCTION app.check_sales_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_me uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_filed uuid;
  v_branch uuid;
  v_base text;
  v_registered boolean;
  v_inclusive boolean;
  v_lines integer;
  v_gross numeric;
  v_discount numeric;
  v_value numeric;
  v_tax numeric;
  v_further numeric;
  v_extra numeric;
  v_total numeric;
  v_limit numeric;
  v_receivable numeric;
  v_orders numeric;
  v_over boolean := false;
  v_customer public.customers%ROWTYPE;
  v_address text;
  v_changes jsonb;
  v_what jsonb;
  -- What submitting, holding and cancelling may change; everything else stays as it stood.
  v_moves text[] := ARRAY['status', 'number', 'submitted_at', 'submitted_by',
    'buyer_name', 'buyer_ntn', 'buyer_cnic', 'buyer_strn', 'buyer_registration_type', 'buyer_atl_status', 'buyer_province', 'buyer_address',
    'credit_limit', 'credit_exposure', 'credit_override_reason', 'credit_override_by', 'held_at', 'held_by',
    'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by', 'posted_txid'];
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  -- Every check below reads what is committed now. A transaction that reads an older picture
  -- of the database could slip a line or a second order past them, so it is not let in.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NOT app.writes_sales_document(v_role, v_scope, v_me, OLD.branch_id, OLD.created_by, OLD.salesperson_id, OLD.kind) THEN
      RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'only a draft is thrown away; a submitted document is cancelled' USING ERRCODE = 'SE050';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Who may write the row is asked here as well as by the policies, for this row and at this
  -- moment: the policies read the company and the role once per statement, each on its own.
  IF NEW.updated_by IS DISTINCT FROM v_me
     OR NOT app.writes_sales_document(v_role, v_scope, v_me, NEW.branch_id, NEW.created_by, NEW.salesperson_id, NEW.kind)
     OR (TG_OP = 'UPDATE' AND NOT app.writes_sales_document(v_role, v_scope, v_me, OLD.branch_id, OLD.created_by, OLD.salesperson_id, OLD.kind))
     OR (TG_OP = 'INSERT' AND NEW.created_by IS DISTINCT FROM v_me) THEN
    RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  SELECT w.branch_id INTO v_branch FROM public.warehouses w WHERE w.tenant_id = NEW.tenant_id AND w.id = NEW.warehouse_id;
  IF FOUND AND v_branch IS DISTINCT FROM NEW.branch_id THEN
    RAISE EXCEPTION 'a document belongs to the branch of its warehouse' USING ERRCODE = 'SE052';
  END IF;
  -- Until foreign-currency sales exist, every document is in the base currency at a rate of one.
  -- A rate left free would let an order weigh next to nothing against the credit limit.
  SELECT c.code INTO v_base FROM public.currencies c WHERE c.tenant_id = NEW.tenant_id AND c.is_base;
  IF NEW.currency IS DISTINCT FROM v_base OR NEW.exchange_rate <> 1 THEN
    RAISE EXCEPTION 'a sales document is in the company''s base currency' USING ERRCODE = 'SE052';
  END IF;
  -- A delivery note is made from one sales order: for its customer, from its warehouse. Nothing
  -- else has a source yet.
  IF NEW.kind = 'delivery' THEN
    -- The order must be one the writer may see: a salesperson delivers their own orders, not a
    -- colleague's. The note is filed under whoever the order is filed under, or failing that
    -- whoever wrote it, so the people who see the order see its delivery notes.
    SELECT coalesce(o.salesperson_id, o.created_by) INTO v_filed FROM public.sales_documents o
      WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'order'
        AND o.customer_id = NEW.customer_id AND o.warehouse_id = NEW.warehouse_id
        AND (TG_OP <> 'INSERT' OR o.status = 'submitted')
        AND (v_role <> 'salesperson' OR o.created_by = v_me OR o.salesperson_id IS NOT DISTINCT FROM v_me);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'a delivery note is made from a submitted sales order, for its customer, from its warehouse' USING ERRCODE = 'SE066';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.salesperson_id := v_filed;
    ELSIF OLD.status = 'draft' THEN
      NEW.salesperson_id := v_filed;
    END IF;
  ELSIF NEW.kind = 'invoice' THEN
    -- A sales invoice is made from a posted delivery note, which it bills, or from a sales
    -- order, which it delivers and bills at once: for the same customer, from the same
    -- warehouse, and one the writer may see. It is filed under whoever its source is.
    SELECT coalesce(o.salesperson_id, o.created_by) INTO v_filed FROM public.sales_documents o
      WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind IN ('order', 'delivery')
        AND o.customer_id = NEW.customer_id AND o.warehouse_id = NEW.warehouse_id
        AND (TG_OP <> 'INSERT' OR o.status = 'submitted')
        AND (v_role <> 'salesperson' OR o.created_by = v_me OR o.salesperson_id IS NOT DISTINCT FROM v_me);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'a sales invoice is made from a submitted sales order or a posted delivery note, for its customer, from its warehouse' USING ERRCODE = 'SE066';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.salesperson_id := v_filed;
    ELSIF OLD.status = 'draft' THEN
      NEW.salesperson_id := v_filed;
    END IF;
  ELSIF NEW.source_document_id IS NOT NULL THEN
    RAISE EXCEPTION 'only a delivery note or a sales invoice is made from another document' USING ERRCODE = 'SE052';
  END IF;
  -- The day an invoice falls due is worked out when it is posted, here; until then there is none.
  IF NEW.status IN ('draft', 'on_hold') THEN
    NEW.due_date := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a document starts as a draft' USING ERRCODE = 'SE050';
    END IF;
    IF NEW.kind NOT IN ('quotation', 'order', 'delivery', 'invoice') THEN
      RAISE EXCEPTION 'that kind of sales document cannot be written yet' USING ERRCODE = 'SE050';
    END IF;
    -- A draft carries nothing that only submitting, approving or FBR may write.
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    NEW.fbr_invoice_number := NULL;
    NEW.fbr_submission_id := NULL;
    NEW.fbr_status := NULL;
    NEW.offline_flag := false;
    -- Only the posting functions say a document was posted by them.
    NEW.posted_txid := NULL;
    RETURN NEW;
  END IF;

  IF NEW.kind <> OLD.kind OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at OR NEW.source_document_id IS DISTINCT FROM OLD.source_document_id THEN
    RAISE EXCEPTION 'what a document is, what it was made from and who wrote it never change' USING ERRCODE = 'SE050';
  END IF;
  IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    RETURN NEW;
  END IF;
  IF OLD.status IN ('submitted', 'cancelled') AND NOT (OLD.status = 'submitted' AND NEW.status = 'cancelled') THEN
    RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
  END IF;
  IF NOT ((OLD.status = 'draft' AND NEW.status IN ('on_hold', 'submitted')) OR (OLD.status = 'on_hold' AND NEW.status IN ('draft', 'submitted')) OR (OLD.status = 'submitted' AND NEW.status = 'cancelled')) THEN
    RAISE EXCEPTION 'a sales document cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'SE050';
  END IF;
  -- From here on the document moves on, and moves on as it stands.
  IF (to_jsonb(NEW) - v_moves) IS DISTINCT FROM (to_jsonb(OLD) - v_moves) THEN
    RAISE EXCEPTION 'a document is submitted, held, sent back or cancelled as it stands' USING ERRCODE = 'SE052';
  END IF;

  IF NEW.status = 'draft' THEN
    -- Sent back, or taken back: it is a draft again and can be changed.
    NEW.held_at := NULL;
    NEW.held_by := NULL;
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.release', 'sales_document', NEW.id, jsonb_build_object('status', 'on_hold'), jsonb_build_object('status', 'draft'));
    RETURN NEW;
  END IF;

  IF NEW.status = 'cancelled' THEN
    IF NEW.cancelled_by IS DISTINCT FROM v_me THEN
      RAISE EXCEPTION 'a document is cancelled in the name of whoever cancels it' USING ERRCODE = 'SE052';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by']) THEN
      RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
    END IF;
    -- Goods that have left against an order keep the order alive: the delivery notes are cancelled first.
    IF OLD.kind = 'order' AND EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = OLD.tenant_id AND d.source_document_id = OLD.id AND d.kind IN ('delivery', 'invoice') AND d.status = 'submitted'
    ) THEN
      RAISE EXCEPTION 'an order with goods delivered or invoiced is not cancelled' USING ERRCODE = 'SE065';
    END IF;
    -- A delivery note that has been billed stays: the invoice says what it delivered.
    IF OLD.kind = 'delivery' AND EXISTS (
      SELECT 1 FROM public.sales_documents i
      WHERE i.tenant_id = OLD.tenant_id AND i.source_document_id = OLD.id AND i.kind = 'invoice' AND i.status = 'submitted'
    ) THEN
      RAISE EXCEPTION 'a delivery note that has been invoiced is not cancelled' USING ERRCODE = 'SE073';
    END IF;
    -- A posted invoice is in the books and with the customer: it is corrected by a credit note.
    IF OLD.kind = 'invoice' THEN
      RAISE EXCEPTION 'a posted sales invoice is not cancelled; it is corrected by a credit note' USING ERRCODE = 'SE072';
    END IF;
    NEW.cancelled_at := now();
    NEW.cancel_reason := btrim(NEW.cancel_reason);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_' || NEW.kind || '.cancel', 'sales_document', NEW.id,
        jsonb_build_object('number', OLD.number, 'status', 'submitted'), jsonb_build_object('number', OLD.number, 'status', 'cancelled', 'reason', NEW.cancel_reason));
    RETURN NEW;
  END IF;

  -- Held or submitted: the document must be whole.
  SELECT count(*), coalesce(sum(round(l.quantity * l.unit_price, 2)), 0), coalesce(sum(l.discount_amount), 0), coalesce(sum(l.value), 0),
         coalesce(sum(l.tax_amount), 0), coalesce(sum(l.further_tax_amount), 0), coalesce(sum(l.extra_tax_amount), 0), coalesce(sum(l.total), 0)
    INTO v_lines, v_gross, v_discount, v_value, v_tax, v_further, v_extra, v_total
    FROM public.sales_lines l WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a document needs at least one line' USING ERRCODE = 'SE052';
  END IF;
  IF NEW.gross_total <> v_gross OR NEW.discount_total <> v_discount OR NEW.value_total <> v_value OR NEW.tax_total <> v_tax
     OR NEW.further_tax_total <> v_further OR NEW.extra_tax_total <> v_extra OR NEW.total <> v_total THEN
    RAISE EXCEPTION 'the totals of a document are those of its lines' USING ERRCODE = 'SE052';
  END IF;
  -- Each line is its quantity at its price, less its discount: before tax, or with the tax inside.
  IF EXISTS (
    SELECT 1 FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id
      AND (CASE WHEN NEW.prices_include_tax THEN l.total - l.extra_tax_amount ELSE l.value END) <> round(l.quantity * l.unit_price, 2) - l.discount_amount
  ) THEN
    RAISE EXCEPTION 'a line comes to its quantity at its price, less its discount' USING ERRCODE = 'SE052';
  END IF;
  -- Whether the document carries sales tax, and whether its prices hold the tax, is the company's answer, not the writer's.
  SELECT s.sales_tax_registered, s.sales_tax_registered AND s.prices_include_tax INTO v_registered, v_inclusive
    FROM public.company_setup s WHERE s.tenant_id = NEW.tenant_id;
  IF NEW.taxed IS DISTINCT FROM coalesce(v_registered, false) OR NEW.prices_include_tax IS DISTINCT FROM coalesce(v_inclusive, false) THEN
    RAISE EXCEPTION 'a document carries sales tax as the company is registered for it' USING ERRCODE = 'SE052';
  END IF;
  IF NOT NEW.taxed AND EXISTS (
    SELECT 1 FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id
      AND (l.tax_amount <> 0 OR l.further_tax_amount <> 0 OR l.extra_tax_amount <> 0 OR l.tax_rate <> 0 OR l.further_tax_rate <> 0 OR l.tax_kind IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'a document without sales tax has no tax on its lines' USING ERRCODE = 'SE052';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sales_line_salespeople s
    WHERE s.tenant_id = NEW.tenant_id AND s.document_id = NEW.id
    GROUP BY s.line_id HAVING sum(s.share_percent) <> 100
  ) OR (NEW.kind <> 'invoice' AND EXISTS (
    SELECT 1 FROM public.sales_line_salespeople s
    WHERE s.tenant_id = NEW.tenant_id AND s.document_id = NEW.id
      AND NOT EXISTS (SELECT 1 FROM public.memberships m WHERE m.tenant_id = s.tenant_id AND m.user_id = s.user_id AND m.active AND m.role IN ('owner', 'sales_manager', 'salesperson'))
  )) THEN
    RAISE EXCEPTION 'the salespeople''s shares of a line come to 100, among active members of the sales team' USING ERRCODE = 'SE052';
  END IF;
  IF NEW.kind = 'delivery' AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'order' AND o.status = 'submitted' AND o.document_date <= NEW.document_date
  ) THEN
    RAISE EXCEPTION 'a delivery note is posted against a submitted sales order, on or after its date' USING ERRCODE = 'SE066';
  END IF;
  IF NEW.kind = 'invoice' AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind IN ('order', 'delivery') AND o.status = 'submitted' AND o.document_date <= NEW.document_date
  ) THEN
    RAISE EXCEPTION 'a sales invoice is posted against a submitted sales order or a posted delivery note, on or after its date' USING ERRCODE = 'SE066';
  END IF;
  SELECT c.* INTO v_customer FROM public.customers c WHERE c.tenant_id = NEW.tenant_id AND c.id = NEW.customer_id;
  -- Goods already delivered are billed even if the customer has been archived since.
  IF v_customer.archived_at IS NOT NULL AND NOT (NEW.kind = 'invoice' AND EXISTS (
    SELECT 1 FROM public.sales_documents o WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'delivery'
  )) THEN
    RAISE EXCEPTION 'the customer is archived' USING ERRCODE = 'SE052';
  END IF;

  IF NEW.kind = 'order' THEN
    -- One order at a time per customer, so two cannot both fit under the same limit.
    PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || NEW.tenant_id::text || ':' || NEW.customer_id::text, 0));
    SELECT k.credit_limit, k.receivable, k.open_orders INTO v_limit, v_receivable, v_orders FROM app.customer_credit(NEW.customer_id, NEW.id) k;
    v_over := v_limit IS NOT NULL AND v_receivable + v_orders + NEW.total > v_limit;
  END IF;
  v_what := jsonb_build_object('kind', NEW.kind, 'customer', v_customer.name, 'date', NEW.document_date, 'lines', v_lines, 'total', NEW.total::text);

  IF NEW.status = 'on_hold' THEN
    IF NOT v_over THEN
      RAISE EXCEPTION 'only an order over its customer''s credit limit waits for approval' USING ERRCODE = 'SE054';
    END IF;
    IF NEW.held_by IS DISTINCT FROM v_me THEN
      RAISE EXCEPTION 'an order is held in the name of whoever holds it' USING ERRCODE = 'SE052';
    END IF;
    NEW.held_at := now();
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.hold', 'sales_document', NEW.id,
        v_what || jsonb_build_object('creditLimit', v_limit::text, 'owed', v_receivable::text, 'otherOrders', v_orders::text));
    RETURN NEW;
  END IF;

  -- Submitted. Who submitted it, when, to whom and under what number are the database's own answers.
  IF NEW.submitted_by IS DISTINCT FROM v_me THEN
    RAISE EXCEPTION 'a document is submitted in the name of whoever submits it' USING ERRCODE = 'SE052';
  END IF;
  SELECT nullif(concat_ws(', ', a.line, a.city), '') INTO v_address FROM public.party_addresses a
    WHERE a.tenant_id = NEW.tenant_id AND a.customer_id = NEW.customer_id AND a.is_primary;
  NEW.buyer_name := v_customer.name;
  NEW.buyer_ntn := v_customer.ntn;
  NEW.buyer_cnic := v_customer.cnic;
  NEW.buyer_strn := v_customer.strn;
  NEW.buyer_registration_type := v_customer.registration_type::text;
  NEW.buyer_atl_status := v_customer.atl_status::text;
  NEW.buyer_province := v_customer.province::text;
  NEW.buyer_address := v_address;
  NEW.submitted_at := now();
  NEW.held_at := NULL;
  NEW.held_by := NULL;
  -- An invoice falls due after the customer's credit days, counted from its own date.
  IF NEW.kind = 'invoice' THEN
    NEW.due_date := NEW.document_date + coalesce(v_customer.credit_days, 0);
  END IF;
  IF NEW.kind = 'order' THEN
    NEW.credit_limit := v_limit;
    NEW.credit_exposure := v_receivable + v_orders;
  ELSE
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
  END IF;
  IF v_over THEN
    IF v_role IS DISTINCT FROM 'owner' THEN
      RAISE EXCEPTION 'the order takes the customer over the credit limit; only an owner approves it' USING ERRCODE = 'SE051';
    END IF;
    IF NEW.credit_override_reason IS NULL THEN
      RAISE EXCEPTION 'an order over the credit limit is approved with a reason' USING ERRCODE = 'SE053';
    END IF;
    NEW.credit_override_reason := btrim(NEW.credit_override_reason);
    NEW.credit_override_by := v_me;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.credit_override', 'sales_document', NEW.id,
        jsonb_build_object('creditLimit', v_limit::text, 'owed', v_receivable::text, 'otherOrders', v_orders::text),
        jsonb_build_object('orderTotal', NEW.total::text, 'over', (v_receivable + v_orders + NEW.total - v_limit)::text, 'reason', NEW.credit_override_reason));
  ELSE
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
  END IF;
  -- The number comes from the series here and nowhere else, so it cannot be invented, and a
  -- date with no open fiscal period is refused (SE001, SE002).
  NEW.number := app.next_document_number(CASE NEW.kind WHEN 'quotation' THEN 'QT' WHEN 'order' THEN 'SO' WHEN 'delivery' THEN 'DN' WHEN 'invoice' THEN 'SI' ELSE '??' END, NEW.document_date);
  -- Every line sold at a price that is not the price lists', or with a discount, is named in the log.
  SELECT jsonb_agg(jsonb_build_object('item', l.description, 'list', l.list_price::text, 'charged', l.unit_price::text,
           'discount', CASE WHEN l.discount_percent IS NOT NULL THEN trim_scale(l.discount_percent)::text || '%' WHEN l.discount_amount <> 0 THEN l.discount_amount::text END) ORDER BY l.line_no)
    INTO v_changes
    FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id AND (l.discount_percent IS NOT NULL OR l.discount_amount <> 0 OR l.list_price IS DISTINCT FROM l.unit_price);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (NEW.tenant_id, v_me, v_role, 'sales_' || NEW.kind || '.submit', 'sales_document', NEW.id,
      jsonb_build_object('number', NEW.number) || v_what || CASE WHEN v_changes IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('priceChanges', v_changes) END);
  RETURN NEW;
END $$;
--> statement-breakpoint
-- The lines' guard, with one more rule: a line of an invoice bills a line of what the invoice
-- was made from, the same item in the same unit at the same price and discount.
CREATE OR REPLACE FUNCTION app.check_sales_document_part() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid;
  v_document uuid;
  v_status text;
  v_branch uuid;
  v_created_by uuid;
  v_salesperson uuid;
  v_kind text;
  v_source uuid;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    IF TG_TABLE_NAME = 'sales_document_links' THEN
      v_document := OLD.to_document_id;
    ELSE
      v_document := OLD.document_id;
    END IF;
  ELSE
    v_tenant := NEW.tenant_id;
    IF TG_TABLE_NAME = 'sales_document_links' THEN
      v_document := NEW.to_document_id;
    ELSE
      v_document := NEW.document_id;
    END IF;
  END IF;
  IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- As for the document itself: a transaction reading an older picture could add a line to a
  -- document that has since been submitted.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.status, d.branch_id, d.created_by, d.salesperson_id, d.kind, d.source_document_id INTO v_status, v_branch, v_created_by, v_salesperson, v_kind, v_source FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = v_document
    FOR SHARE;
  -- The document must be one this member may write, asked for this row and at this moment.
  IF FOUND AND NOT app.writes_sales_document(app.tenant_role(), app.tenant_branch_ids(), app.current_user_id(), v_branch, v_created_by, v_salesperson, v_kind) THEN
    RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF FOUND AND v_status <> 'draft' THEN
    RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  NEW.created_at := now();
  IF TG_TABLE_NAME = 'sales_lines' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.items i
      WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.item_id
        AND ((i.base_unit_id = NEW.unit_id AND NEW.unit_factor = 1)
          OR EXISTS (SELECT 1 FROM public.item_units u WHERE u.tenant_id = i.tenant_id AND u.item_id = i.id AND u.unit_id = NEW.unit_id AND u.factor = NEW.unit_factor))
    ) THEN
      RAISE EXCEPTION 'a line is sold in one of its item''s own units' USING ERRCODE = 'SE052';
    END IF;
    -- A discount is its percentage of the quantity at the price, to the paisa, and nothing else:
    -- an amount typed beside a percentage could make a line bill anything from nil to the full price.
    IF NEW.discount_amount <> (CASE WHEN NEW.discount_percent IS NULL THEN 0 ELSE round(round(NEW.quantity * NEW.unit_price, 2) * NEW.discount_percent / 100, 2) END) THEN
      RAISE EXCEPTION 'a line''s discount is its percentage of the quantity at the price' USING ERRCODE = 'SE052';
    END IF;
    -- A line of a delivery note delivers one line of the note's own order: the same item, in the
    -- same unit. No other kind of document has a source line yet.
    IF v_kind = 'delivery' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.sales_lines o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_line_id AND o.document_id = v_source
          AND o.item_id = NEW.item_id AND o.unit_id = NEW.unit_id AND o.unit_factor = NEW.unit_factor
          AND o.unit_price = NEW.unit_price AND o.discount_percent IS NOT DISTINCT FROM NEW.discount_percent
          AND o.list_price IS NOT DISTINCT FROM NEW.list_price AND o.price_source IS NOT DISTINCT FROM NEW.price_source
      ) THEN
        RAISE EXCEPTION 'a line of a delivery note delivers a line of its order, in the same unit and at the order''s price' USING ERRCODE = 'SE052';
      END IF;
      -- Tax belongs to the invoice: a delivery note values the goods and nothing more.
      IF NEW.tax_amount <> 0 OR NEW.further_tax_amount <> 0 OR NEW.extra_tax_amount <> 0 OR NEW.tax_rate <> 0 OR NEW.further_tax_rate <> 0
         OR NEW.tax_kind IS NOT NULL OR NEW.tax_category_id IS NOT NULL THEN
        RAISE EXCEPTION 'a delivery note carries no tax' USING ERRCODE = 'SE052';
      END IF;
    ELSIF v_kind = 'invoice' THEN
      -- A line of an invoice bills one line of what the invoice was made from: the same item,
      -- in the same unit, at its price and discount. The tax is the invoice's own.
      IF NOT EXISTS (
        SELECT 1 FROM public.sales_lines o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_line_id AND o.document_id = v_source
          AND o.item_id = NEW.item_id AND o.unit_id = NEW.unit_id AND o.unit_factor = NEW.unit_factor
          AND o.unit_price = NEW.unit_price AND o.discount_percent IS NOT DISTINCT FROM NEW.discount_percent
          AND o.list_price IS NOT DISTINCT FROM NEW.list_price AND o.price_source IS NOT DISTINCT FROM NEW.price_source
      ) THEN
        RAISE EXCEPTION 'a line of a sales invoice bills a line of what it was made from, in the same unit and at its price' USING ERRCODE = 'SE052';
      END IF;
    ELSIF NEW.source_line_id IS NOT NULL THEN
      RAISE EXCEPTION 'only a line of a delivery note or a sales invoice follows another line' USING ERRCODE = 'SE052';
    END IF;
  ELSIF TG_TABLE_NAME = 'sales_line_salespeople' THEN
    -- An invoice's shares are its order's, copied by the posting function; whoever has left the sales team since still has theirs.
    IF v_kind <> 'invoice' AND NOT EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.tenant_id = NEW.tenant_id AND m.user_id = NEW.user_id AND m.active AND m.role IN ('owner', 'sales_manager', 'salesperson')
    ) THEN
      RAISE EXCEPTION 'a share of a sale goes to an active member of the sales team' USING ERRCODE = 'SE052';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint

-- ── hand-written: how far an order has gone ─────────────────────────────────────────────────────
-- For every line of one sales order: how much has left the warehouse against it (posted
-- delivery notes, and posted invoices made straight from the order), and how much has been
-- invoiced (those same invoices, and the invoices of its delivery notes). It replaces
-- app.order_delivered of drizzle/0017_delivery_notes.sql, with the same rule for who may ask.
DROP FUNCTION app.order_delivered(uuid);
--> statement-breakpoint
CREATE FUNCTION app.order_progress(p_order uuid) RETURNS TABLE (line_id uuid, delivered numeric, delivered_base numeric, invoiced numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = v_tenant AND o.id = p_order AND o.kind = 'order'
      AND (v_role IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson') OR (v_role = 'warehouse_manager' AND o.status = 'submitted'))
      AND (v_role <> 'salesperson' OR o.created_by = v_user OR o.salesperson_id IS NOT DISTINCT FROM v_user)
      AND (v_scope IS NULL OR o.branch_id = ANY (v_scope))
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT ol.id,
      coalesce(gone.quantity, 0), coalesce(gone.base_quantity, 0),
      coalesce((
        SELECT sum(l.quantity)
        FROM public.sales_lines l
        JOIN public.sales_documents d ON d.tenant_id = l.tenant_id AND d.id = l.document_id
        WHERE l.tenant_id = v_tenant AND d.kind = 'invoice' AND d.status = 'submitted'
          AND (l.source_line_id = ol.id OR l.source_line_id IN (
            SELECT dl.id FROM public.sales_lines dl
            JOIN public.sales_documents dd ON dd.tenant_id = dl.tenant_id AND dd.id = dl.document_id
            WHERE dl.tenant_id = v_tenant AND dl.source_line_id = ol.id AND dd.kind = 'delivery'))
      ), 0)
    FROM public.sales_lines ol
    LEFT JOIN LATERAL (
      SELECT sum(l.quantity) AS quantity, sum(l.base_quantity) AS base_quantity
      FROM public.sales_lines l
      JOIN public.sales_documents d ON d.tenant_id = l.tenant_id AND d.id = l.document_id
      WHERE l.tenant_id = v_tenant AND l.source_line_id = ol.id AND d.kind IN ('delivery', 'invoice') AND d.status = 'submitted'
    ) gone ON true
    WHERE ol.tenant_id = v_tenant AND ol.document_id = p_order;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.order_progress(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.order_progress(uuid) TO app_runtime;
--> statement-breakpoint
-- Posting a delivery note, written out again with one change: what has already left against a
-- line of the order now counts the invoices made straight from the order as well.
CREATE OR REPLACE FUNCTION app.post_delivery(p_document uuid) RETURNS TABLE (number text, journal_id uuid, cost numeric)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.sales_documents%ROWTYPE;
  v_order public.sales_documents%ROWTYPE;
  v_line record;
  v_delivered numeric;
  v_total numeric := 0;
  v_number text;
  v_journal uuid;
  v_cogs uuid;
  v_inventory uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'sales_manager', 'salesperson', 'warehouse_manager') THEN
    RAISE EXCEPTION 'this role cannot post a delivery note' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.* INTO v_doc FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = p_document AND d.kind = 'delivery'
    FOR UPDATE;
  -- A note outside a member's branches, or another salesperson's, does not exist for that member.
  IF NOT FOUND
     OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope)))
     OR (v_role = 'salesperson' AND v_doc.created_by <> v_user AND v_doc.salesperson_id IS DISTINCT FROM v_user) THEN
    RAISE EXCEPTION 'no such delivery note in this company' USING ERRCODE = 'SE063';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft delivery note is posted' USING ERRCODE = 'SE050';
  END IF;
  -- The order is held until the transaction ends: two notes for one order take their turn, and
  -- the order cannot be cancelled meanwhile.
  SELECT o.* INTO v_order FROM public.sales_documents o
    WHERE o.tenant_id = v_tenant AND o.id = v_doc.source_document_id AND o.kind = 'order'
    FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'submitted' THEN
    RAISE EXCEPTION 'a delivery note is posted against a submitted sales order' USING ERRCODE = 'SE066';
  END IF;
  IF v_doc.document_date < v_order.document_date THEN
    RAISE EXCEPTION 'a delivery note is dated on or after its order' USING ERRCODE = 'SE067';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.document_date);

  -- Whether the goods and the journal went with it is asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.sales_documents_posted DEFERRED;
  -- Submitted first: the document's own guard checks it is whole, numbers it, copies the buyer
  -- and writes its audit row. From here on its lines cannot change.
  UPDATE public.sales_documents d SET status = 'submitted', submitted_by = v_user, updated_by = v_user, posted_txid = txid_current()
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id
    RETURNING d.number INTO v_number;

  FOR v_line IN
    SELECT l.id, l.item_id, l.base_quantity, l.source_line_id, o.base_quantity AS ordered, i.code
    FROM public.sales_lines l
    JOIN public.sales_lines o ON o.tenant_id = l.tenant_id AND o.id = l.source_line_id
    JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    WHERE l.tenant_id = v_tenant AND l.document_id = v_doc.id
    -- Item by item, the same way round for every note, so two notes never wait on each other.
    ORDER BY l.item_id, l.line_no
  LOOP
    -- What has left against this line of the order: posted delivery notes, this one included, and posted invoices made straight from the order.
    SELECT coalesce(sum(p.base_quantity), 0) INTO v_delivered
      FROM public.sales_lines p
      JOIN public.sales_documents pd ON pd.tenant_id = p.tenant_id AND pd.id = p.document_id
      WHERE p.tenant_id = v_tenant AND p.source_line_id = v_line.source_line_id AND pd.kind IN ('delivery', 'invoice') AND pd.status = 'submitted';
    IF v_delivered > v_line.ordered THEN
      RAISE EXCEPTION 'more of % than the order still has to deliver: % ordered, % already gone, % on this note',
        v_line.code, v_line.ordered, v_delivered - v_line.base_quantity, v_line.base_quantity USING ERRCODE = 'SE061';
    END IF;
    v_total := v_total + app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.document_date, -v_line.base_quantity, NULL, 'delivery_note', v_doc.id, v_line.id);
  END LOOP;

  -- Goods that cost nothing leave no journal: there is nothing to move between accounts.
  IF v_total > 0 THEN
    SELECT a.id INTO v_cogs FROM public.accounts a WHERE a.tenant_id = v_tenant AND a.is_control AND a.control_type = 'cogs';
    SELECT a.id INTO v_inventory FROM public.accounts a WHERE a.tenant_id = v_tenant AND a.is_control AND a.control_type = 'inventory';
    IF v_cogs IS NULL OR v_inventory IS NULL THEN
      RAISE EXCEPTION 'the chart of accounts has no stock or cost of goods sold account' USING ERRCODE = 'SE064';
    END IF;
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, v_doc.document_date, 'delivery_note', v_doc.id, v_number, left('Goods delivered against sales order ' || v_order.number, 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, 1, v_cogs, v_total, 0, 'Cost of the goods delivered'),
             (v_tenant, v_journal, 2, v_inventory, 0, v_total, 'Goods out of stock');
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', v_doc.document_date, 'source', 'delivery_note', 'sourceId', v_doc.id, 'number', v_number, 'lines', 2, 'total', v_total::text));
  END IF;
  RETURN QUERY SELECT v_number, v_journal, v_total;
END $$;
--> statement-breakpoint

-- ── hand-written: what a customer owes, once orders are invoiced ────────────────────────────────
-- As before, with the part of each order that has been invoiced taken out of "orders already
-- submitted": an invoice is in the receivable from the moment it is posted, and counting it
-- under both would hold the customer's limit against them twice.
CREATE OR REPLACE FUNCTION app.customer_credit(p_customer uuid, p_except uuid DEFAULT NULL)
  RETURNS TABLE (credit_limit numeric, receivable numeric, open_orders numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson', 'recovery_officer') THEN
    RAISE EXCEPTION 'not allowed to see what a customer owes' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN QUERY
    SELECT
      c.credit_limit,
      round(coalesce((
        SELECT sum(l.debit - l.credit)
        FROM public.journal_lines l
        JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
        WHERE l.tenant_id = v_tenant AND l.customer_id = c.id AND a.is_control AND a.control_type IN ('ar', 'customer_advances')
      ), 0), 4),
      round(coalesce((
        SELECT sum(greatest(o.total - coalesce((
          SELECT sum(i.total) FROM public.sales_documents i
          WHERE i.tenant_id = v_tenant AND i.kind = 'invoice' AND i.status = 'submitted'
            AND (i.source_document_id = o.id OR i.source_document_id IN (
              SELECT n.id FROM public.sales_documents n WHERE n.tenant_id = v_tenant AND n.kind = 'delivery' AND n.source_document_id = o.id))
        ), 0), 0))
        FROM public.sales_documents o
        WHERE o.tenant_id = v_tenant AND o.customer_id = c.id AND o.kind = 'order' AND o.status = 'submitted' AND o.id IS DISTINCT FROM p_except
      ), 0), 4)
    FROM public.customers c
    WHERE c.tenant_id = v_tenant AND c.id = p_customer;
END $$;
--> statement-breakpoint
-- ── hand-written: posting a sales invoice ───────────────────────────────────────────────────────
-- Posting a sales invoice is one act of the database, like posting a delivery note. It checks
-- the invoice against what it was made from, marks it submitted (which takes its SI number,
-- copies the buyer and writes the audit row), and posts the journal:
--
--   debit   Trade receivables (the customer)        what the customer now owes
--   credit  Sales                                   the value of the goods before tax
--   credit  Sales tax payable (output tax)          the sales tax, and any extra tax
--   credit  Further tax payable                     the further tax, kept apart: it cannot be
--                                                   set against input tax
--
-- An invoice made from a delivery note bills exactly what that note delivered; the goods have
-- already left stock and their cost is already in the books. An invoice made straight from a
-- sales order delivers as it bills: the goods leave stock here, at their weighted-average
-- cost, and the same journal carries
--
--   debit   Cost of goods sold
--   credit  Stock in trade
--
-- Refused: a delivery note that is already invoiced or not posted (SE070), more than the order
-- still has to deliver (SE061), more than the warehouse holds (SE060), a closed period.
CREATE FUNCTION app.post_sales_invoice(p_document uuid) RETURNS TABLE (number text, journal_id uuid, cost numeric)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.sales_documents%ROWTYPE;
  v_source public.sales_documents%ROWTYPE;
  v_order public.sales_documents%ROWTYPE;
  v_line record;
  v_delivered numeric;
  v_cost numeric := 0;
  v_number text;
  v_journal uuid;
  v_account uuid;
  v_line_no integer := 0;
  v_tax numeric;
  v_excess numeric;
  v_limit numeric;
  v_exposure numeric;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'sales_manager', 'salesperson') THEN
    RAISE EXCEPTION 'this role cannot post a sales invoice' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.* INTO v_doc FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = p_document AND d.kind = 'invoice'
    FOR UPDATE;
  -- An invoice outside a member's branches, or another salesperson's, does not exist for that member.
  IF NOT FOUND
     OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope)))
     OR (v_role = 'salesperson' AND v_doc.created_by <> v_user AND v_doc.salesperson_id IS DISTINCT FROM v_user) THEN
    RAISE EXCEPTION 'no such sales invoice in this company' USING ERRCODE = 'SE063';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft sales invoice is posted' USING ERRCODE = 'SE050';
  END IF;
  SELECT s.* INTO v_source FROM public.sales_documents s WHERE s.tenant_id = v_tenant AND s.id = v_doc.source_document_id;
  -- The order behind the invoice is held until the transaction ends: its invoices and delivery
  -- notes take their turn, and it cannot be cancelled meanwhile.
  SELECT o.* INTO v_order FROM public.sales_documents o
    WHERE o.tenant_id = v_tenant AND o.kind = 'order' AND o.id = (CASE WHEN v_source.kind = 'delivery' THEN v_source.source_document_id ELSE v_source.id END)
    FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'submitted' THEN
    RAISE EXCEPTION 'a sales invoice is posted against a submitted sales order' USING ERRCODE = 'SE066';
  END IF;
  IF v_doc.document_date < v_source.document_date THEN
    RAISE EXCEPTION 'a sales invoice is dated on or after what it was made from' USING ERRCODE = 'SE067';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.document_date);
  -- What the customer owes is about to change: orders being weighed against the limit wait for it.
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_tenant::text || ':' || v_doc.customer_id::text, 0));

  IF v_source.kind = 'delivery' THEN
    -- The whole note, once: its lines and quantities, no more and no fewer.
    SELECT d.* INTO v_source FROM public.sales_documents d WHERE d.tenant_id = v_tenant AND d.id = v_source.id FOR UPDATE;
    IF v_source.status <> 'submitted' OR EXISTS (
      SELECT 1 FROM public.sales_documents i
      WHERE i.tenant_id = v_tenant AND i.source_document_id = v_source.id AND i.kind = 'invoice' AND i.status = 'submitted'
    ) THEN
      RAISE EXCEPTION 'a delivery note is invoiced once, while it stands' USING ERRCODE = 'SE070';
    END IF;
    IF (SELECT count(*) FROM public.sales_lines il WHERE il.tenant_id = v_tenant AND il.document_id = v_doc.id)
         <> (SELECT count(*) FROM public.sales_lines dl WHERE dl.tenant_id = v_tenant AND dl.document_id = v_source.id)
       OR EXISTS (
         SELECT 1 FROM public.sales_lines il
         WHERE il.tenant_id = v_tenant AND il.document_id = v_doc.id
           AND NOT EXISTS (SELECT 1 FROM public.sales_lines dl WHERE dl.tenant_id = v_tenant AND dl.id = il.source_line_id AND dl.document_id = v_source.id AND dl.base_quantity = il.base_quantity)
       ) THEN
      RAISE EXCEPTION 'an invoice made from a delivery note bills exactly what the note delivered' USING ERRCODE = 'SE071';
    END IF;
  END IF;

  -- The salespeople of an invoice are those of its order, line by line, whatever the draft
  -- says: commission follows the invoice, and a share is not the writer's to move.
  DELETE FROM public.sales_line_salespeople s WHERE s.tenant_id = v_tenant AND s.document_id = v_doc.id;
  INSERT INTO public.sales_line_salespeople (tenant_id, document_id, line_id, user_id, share_percent, created_by)
    SELECT v_tenant, v_doc.id, il.id, os.user_id, os.share_percent, v_user
    FROM public.sales_lines il
    JOIN public.sales_lines sl ON sl.tenant_id = il.tenant_id AND sl.id = il.source_line_id
    JOIN public.sales_line_salespeople os ON os.tenant_id = il.tenant_id AND os.line_id = (CASE WHEN v_source.kind = 'delivery' THEN sl.source_line_id ELSE sl.id END)
    WHERE il.tenant_id = v_tenant AND il.document_id = v_doc.id;

  -- The order was weighed against the customer's credit limit when it was submitted. An
  -- invoice for no more than the order still has to bill adds nothing to what was weighed.
  -- One for more (a rate that has risen, or figures written past the app) is weighed for the
  -- difference, and over the limit only an owner posts it.
  v_excess := v_doc.total - greatest(v_order.total - coalesce((
    SELECT sum(i.total) FROM public.sales_documents i
    WHERE i.tenant_id = v_tenant AND i.kind = 'invoice' AND i.status = 'submitted'
      AND (i.source_document_id = v_order.id OR i.source_document_id IN (
        SELECT n.id FROM public.sales_documents n WHERE n.tenant_id = v_tenant AND n.kind = 'delivery' AND n.source_document_id = v_order.id))
  ), 0), 0);
  IF v_excess > 0 AND v_role <> 'owner' THEN
    SELECT k.credit_limit, k.receivable + k.open_orders INTO v_limit, v_exposure FROM app.customer_credit(v_doc.customer_id) k;
    IF v_limit IS NOT NULL AND v_exposure + v_excess > v_limit THEN
      RAISE EXCEPTION 'the invoice takes the customer over the credit limit by more than its order did; only an owner posts it' USING ERRCODE = 'SE051';
    END IF;
  END IF;

  -- Whether the goods and the journal went with it is asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.sales_documents_posted DEFERRED;
  -- Submitted first: the document's own guard checks it is whole, numbers it, copies the buyer
  -- and writes its audit row. From here on its lines cannot change.
  UPDATE public.sales_documents d SET status = 'submitted', submitted_by = v_user, updated_by = v_user, posted_txid = txid_current()
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id
    RETURNING d.* INTO v_doc;
  v_number := v_doc.number;

  IF v_source.kind = 'order' THEN
    -- Straight from the order: the invoice delivers as it bills.
    FOR v_line IN
      SELECT l.id, l.item_id, l.base_quantity, l.source_line_id, o.base_quantity AS ordered, i.code
      FROM public.sales_lines l
      JOIN public.sales_lines o ON o.tenant_id = l.tenant_id AND o.id = l.source_line_id
      JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
      WHERE l.tenant_id = v_tenant AND l.document_id = v_doc.id
      -- Item by item, the same way round for every document, so two never wait on each other.
      ORDER BY l.item_id, l.line_no
    LOOP
      -- What has left against this line of the order: posted delivery notes, and posted invoices made straight from the order, this one included.
      SELECT coalesce(sum(p.base_quantity), 0) INTO v_delivered
        FROM public.sales_lines p
        JOIN public.sales_documents pd ON pd.tenant_id = p.tenant_id AND pd.id = p.document_id
        WHERE p.tenant_id = v_tenant AND p.source_line_id = v_line.source_line_id AND pd.kind IN ('delivery', 'invoice') AND pd.status = 'submitted';
      IF v_delivered > v_line.ordered THEN
        RAISE EXCEPTION 'more of % than the order still has to deliver: % ordered, % already gone, % on this invoice',
          v_line.code, v_line.ordered, v_delivered - v_line.base_quantity, v_line.base_quantity USING ERRCODE = 'SE061';
      END IF;
      v_cost := v_cost + app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.document_date, -v_line.base_quantity, NULL, 'sales_invoice', v_doc.id, v_line.id);
    END LOOP;
  END IF;

  -- An invoice for nothing, of goods that cost nothing, leaves no journal.
  IF v_doc.total > 0 OR v_cost > 0 THEN
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, v_doc.document_date, 'sales_invoice', v_doc.id, v_number, left('Sales invoice to ' || v_doc.buyer_name, 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    IF v_doc.total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'ar'), v_doc.total, 0, 'Invoice ' || v_number, v_doc.customer_id);
    END IF;
    IF v_doc.value_total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'sales'), 0, v_doc.value_total, 'Sales');
    END IF;
    v_tax := v_doc.tax_total + v_doc.extra_tax_total;
    IF v_tax > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'output_tax'), 0, v_tax, 'Sales tax');
    END IF;
    IF v_doc.further_tax_total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'further_tax'), 0, v_doc.further_tax_total, 'Further tax');
    END IF;
    IF v_cost > 0 THEN
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no + 1, app.control_account(v_tenant, 'cogs'), v_cost, 0, 'Cost of the goods sold'),
               (v_tenant, v_journal, v_line_no + 2, app.control_account(v_tenant, 'inventory'), 0, v_cost, 'Goods out of stock');
      v_line_no := v_line_no + 2;
    END IF;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', v_doc.document_date, 'source', 'sales_invoice', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_line_no, 'total', (v_doc.total + v_cost)::text));
  END IF;
  RETURN QUERY SELECT v_number, v_journal, v_cost;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_sales_invoice(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_sales_invoice(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: a posted document has what it posted ──────────────────────────────────────────
-- Asked when the transaction ends, for every delivery note and sales invoice touched in it.
-- It replaces the check of drizzle/0017_delivery_notes.sql and adds invoices:
--
--   a posted delivery note has one move out of stock for each of its lines; a cancelled one has
--   each of those moves undone;
--   a posted invoice made straight from an order has the same, under its own name;
--   a posted invoice for more than nothing has its journal, with the customer owing exactly the
--   invoice's total;
--   and every one of them carries the mark that only the posting functions can write.
--
-- A document marked by hand, past the posting functions, has none of these (nobody else can
-- write a stock move or such a journal), and the whole transaction is refused.
CREATE FUNCTION app.check_document_posted() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.sales_documents%ROWTYPE;
  v_source_kind text;
  v_move_type text;
BEGIN
  IF NEW.kind NOT IN ('delivery', 'invoice') OR session_user = 'postgres' THEN
    RETURN NULL;
  END IF;
  -- The document as it stands now, at the end of the transaction.
  SELECT d.* INTO v_doc FROM public.sales_documents d WHERE d.tenant_id = NEW.tenant_id AND d.id = NEW.id;
  IF NOT FOUND OR v_doc.status = 'draft' THEN
    RETURN NULL;
  END IF;
  -- Posted by the posting function and by nothing else: the app's role cannot write this mark.
  IF v_doc.posted_txid IS NULL THEN
    RAISE EXCEPTION 'a delivery note or a sales invoice is posted only by the database''s own posting function' USING ERRCODE = 'SE068';
  END IF;
  SELECT s.kind INTO v_source_kind FROM public.sales_documents s WHERE s.tenant_id = v_doc.tenant_id AND s.id = v_doc.source_document_id;
  v_move_type := CASE v_doc.kind WHEN 'delivery' THEN 'delivery_note' ELSE 'sales_invoice' END;

  IF v_doc.kind = 'delivery' OR v_source_kind = 'order' THEN
    IF EXISTS (
      SELECT 1 FROM public.sales_lines l
      WHERE l.tenant_id = v_doc.tenant_id AND l.document_id = v_doc.id
        AND (SELECT count(*) FROM public.stock_moves m
             WHERE m.tenant_id = l.tenant_id AND m.source_type = v_move_type AND m.source_id = l.document_id AND m.source_line_id = l.id
               AND m.reverses_move_id IS NULL AND m.quantity = -l.base_quantity AND m.item_id = l.item_id AND m.warehouse_id = v_doc.warehouse_id) <> 1
    ) THEN
      RAISE EXCEPTION 'a document that delivers goods is posted only with its goods taken out of stock' USING ERRCODE = 'SE068';
    END IF;
    IF v_doc.status = 'cancelled' AND EXISTS (
      SELECT 1 FROM public.stock_moves m
      WHERE m.tenant_id = v_doc.tenant_id AND m.source_type = v_move_type AND m.source_id = v_doc.id AND m.reverses_move_id IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.stock_moves r WHERE r.tenant_id = m.tenant_id AND r.reverses_move_id = m.id)
    ) THEN
      RAISE EXCEPTION 'a delivery note is cancelled only with its goods put back into stock' USING ERRCODE = 'SE068';
    END IF;
    IF v_doc.status = 'submitted' AND EXISTS (
      SELECT 1 FROM public.stock_moves r
      JOIN public.stock_moves m ON m.tenant_id = r.tenant_id AND m.id = r.reverses_move_id
      WHERE m.tenant_id = v_doc.tenant_id AND m.source_type = v_move_type AND m.source_id = v_doc.id
    ) THEN
      RAISE EXCEPTION 'a document whose goods were put back is cancelled' USING ERRCODE = 'SE068';
    END IF;
  END IF;

  IF v_doc.kind = 'invoice' AND v_doc.total > 0 AND v_doc.total IS DISTINCT FROM (
    SELECT sum(l.debit - l.credit)
    FROM public.journals j
    JOIN public.journal_lines l ON l.tenant_id = j.tenant_id AND l.journal_id = j.id
    JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
    WHERE j.tenant_id = v_doc.tenant_id AND j.source_type = 'sales_invoice' AND j.source_id = v_doc.id
      AND a.is_control AND a.control_type = 'ar' AND l.customer_id = v_doc.customer_id
  ) THEN
    RAISE EXCEPTION 'a sales invoice is posted only with its journal: the customer owes its total' USING ERRCODE = 'SE068';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_document_posted() FROM PUBLIC;
--> statement-breakpoint
DROP TRIGGER sales_documents_delivery_moved ON public.sales_documents;
