CREATE CONSTRAINT TRIGGER sales_documents_posted
  AFTER UPDATE ON public.sales_documents
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.check_document_posted();
