-- ── hand-written: every journal has the document it claims to be for ────────────────────────────
-- Asked when the transaction ends, for every journal written in it, whoever wrote it: the
-- journal's source must be a document that stands and points back at it. A manual journal or
-- the opening balances name their journal; a delivery note or a sales invoice is found by the
-- journal's source; and a reversal belongs to the document whose journal it reverses. A journal
-- posted by hand through app.post_journal with no document behind it, or one that claims a
-- document of another kind, is refused with the rest of its transaction.
--
-- This closes the gap recorded under "From Step 14" in docs/LATER.md.
CREATE FUNCTION app.check_journal_backed() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_backed boolean;
BEGIN
  v_backed := CASE NEW.source_type
    WHEN 'manual_journal' THEN EXISTS (
      SELECT 1 FROM public.manual_journals m
      WHERE m.tenant_id = NEW.tenant_id AND m.id = NEW.source_id AND m.journal_id = NEW.id AND m.status IN ('posted', 'reversed'))
    WHEN 'opening_balance' THEN EXISTS (
      SELECT 1 FROM public.opening_entries e
      WHERE e.tenant_id = NEW.tenant_id AND e.id = NEW.source_id AND e.journal_id = NEW.id AND e.status IN ('posted', 'reversed'))
    WHEN 'delivery_note' THEN EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = NEW.tenant_id AND d.id = NEW.source_id AND d.kind = 'delivery' AND d.status IN ('submitted', 'cancelled') AND d.number = NEW.document_number)
    WHEN 'sales_invoice' THEN EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = NEW.tenant_id AND d.id = NEW.source_id AND d.kind = 'invoice' AND d.status = 'submitted' AND d.number = NEW.document_number)
    WHEN 'reversal' THEN
      EXISTS (SELECT 1 FROM public.manual_journals m WHERE m.tenant_id = NEW.tenant_id AND m.journal_id = NEW.reverses_journal_id AND m.reversal_journal_id = NEW.id AND m.status = 'reversed')
      OR EXISTS (SELECT 1 FROM public.opening_entries e WHERE e.tenant_id = NEW.tenant_id AND e.journal_id = NEW.reverses_journal_id AND e.reversal_journal_id = NEW.id AND e.status = 'reversed')
      OR EXISTS (
        SELECT 1 FROM public.journals o
        JOIN public.sales_documents d ON d.tenant_id = o.tenant_id AND d.id = o.source_id
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.reverses_journal_id AND o.source_type = 'delivery_note' AND d.kind = 'delivery' AND d.status = 'cancelled')
    ELSE false
  END;
  IF NOT coalesce(v_backed, false) THEN
    RAISE EXCEPTION 'a journal is kept only with the document it was posted for' USING ERRCODE = 'SE074';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_journal_backed() FROM PUBLIC;
--> statement-breakpoint
-- Named to run after the balance check of the same journal: a journal that does not balance
-- says so first.
CREATE CONSTRAINT TRIGGER journals_with_document
  AFTER INSERT ON public.journals
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.check_journal_backed();
--> statement-breakpoint
ALTER TABLE public.journals ENABLE ALWAYS TRIGGER journals_with_document;
--> statement-breakpoint
-- The functions that write a journal keep its checks for the end of the transaction, whatever
-- the caller set before: the balance, as before, and now the document behind it, which is
-- written after the journal in the same transaction. They are written out again with that one
-- line changed; cancelling a delivery note likewise.
CREATE OR REPLACE FUNCTION app.post_journal(
  p_date date,
  p_source_type text,
  p_source_id uuid,
  p_lines jsonb,
  p_memo text DEFAULT NULL,
  p_branch_id uuid DEFAULT NULL,
  p_document_number text DEFAULT NULL
) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_roles public.member_role[] := app.journal_source_roles(p_source_type);
  v_journal uuid;
  v_lines integer;
  v_debit numeric;
  v_credit numeric;
  v_blocked text;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_roles IS NULL THEN
    RAISE EXCEPTION 'unknown kind of journal source' USING ERRCODE = 'check_violation';
  END IF;
  -- The balance is checked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  IF NOT (v_role = ANY (v_roles)) THEN
    RAISE EXCEPTION 'this role cannot post that kind of journal' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- A member limited to some branches posts to one of them, never company-wide.
  IF v_scope IS NOT NULL AND (p_branch_id IS NULL OR NOT (p_branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'a member limited to some branches posts to one of them' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_date IS NULL OR p_source_id IS NULL THEN
    RAISE EXCEPTION 'a journal needs a date and a source' USING ERRCODE = 'check_violation';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) NOT BETWEEN 2 AND 1000 THEN
    RAISE EXCEPTION 'a journal has between 2 and 1,000 lines' USING ERRCODE = 'SE003';
  END IF;
  -- An amount is a real number ("not a number" is a value numeric accepts) and is never rounded
  -- behind anyone's back: more than four decimals is refused.
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_lines) AS l(value)
    WHERE coalesce((l.value->>'debit')::numeric, 0) = 'NaN'::numeric
       OR coalesce((l.value->>'credit')::numeric, 0) = 'NaN'::numeric
       OR coalesce((l.value->>'debit')::numeric, 0) <> round(coalesce((l.value->>'debit')::numeric, 0), 4)
       OR coalesce((l.value->>'credit')::numeric, 0) <> round(coalesce((l.value->>'credit')::numeric, 0), 4)
  ) THEN
    RAISE EXCEPTION 'an amount is a number with at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  -- Cost centres do not exist yet; a line can never be corrected, so none is accepted.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_lines) AS l(value) WHERE nullif(l.value->>'cost_centre_id', '') IS NOT NULL) THEN
    RAISE EXCEPTION 'cost centres are not available yet' USING ERRCODE = 'check_violation';
  END IF;
  -- Before anything is written: an account this kind of journal may not touch.
  SELECT a.code INTO v_blocked
    FROM jsonb_array_elements(p_lines) AS l(value)
    JOIN public.accounts a ON a.tenant_id = v_tenant AND a.id = (l.value->>'account_id')::uuid
    WHERE a.control_type = ANY (app.journal_source_blocked_controls(p_source_type))
    LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'account % cannot be posted to by this kind of journal', v_blocked USING ERRCODE = 'SE005';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);

  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, p_source_type, p_source_id, nullif(btrim(p_document_number), ''), nullif(btrim(p_memo), ''), p_branch_id, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
    SELECT v_tenant, v_journal, l.line_no,
      (l.value->>'account_id')::uuid,
      coalesce((l.value->>'debit')::numeric, 0),
      coalesce((l.value->>'credit')::numeric, 0),
      nullif(btrim(l.value->>'description'), ''),
      (l.value->>'customer_id')::uuid,
      (l.value->>'supplier_id')::uuid
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS l(value, line_no);

  SELECT count(*), sum(l.debit), sum(l.credit) INTO v_lines, v_debit, v_credit
    FROM public.journal_lines l WHERE l.tenant_id = v_tenant AND l.journal_id = v_journal;
  IF v_debit IS DISTINCT FROM v_credit OR v_debit = 'NaN'::numeric THEN
    RAISE EXCEPTION 'the journal does not balance: debits %, credits %', v_debit, v_credit USING ERRCODE = 'SE003';
  END IF;

  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', p_source_type, 'sourceId', p_source_id,
        'number', nullif(btrim(p_document_number), ''), 'lines', v_lines, 'total', v_debit::text));
  RETURN v_journal;
END $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.reverse_journal(p_journal_id uuid, p_date date, p_memo text DEFAULT NULL) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_original public.journals%ROWTYPE;
  v_roles public.member_role[];
  v_journal uuid;
  v_lines integer;
  v_total numeric;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Held until the transaction ends: two reversals of one journal take their turn.
  SELECT j.* INTO v_original FROM public.journals j
    WHERE j.tenant_id = v_tenant AND j.id = p_journal_id
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such journal in this company' USING ERRCODE = 'SE006';
  END IF;
  -- A journal outside a member's branches does not exist for that member.
  IF v_scope IS NOT NULL AND (v_original.branch_id IS NULL OR NOT (v_original.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such journal in this company' USING ERRCODE = 'SE006';
  END IF;
  IF v_original.reverses_journal_id IS NOT NULL AND v_role IN ('owner', 'accountant', 'auditor') THEN
    RAISE EXCEPTION 'a reversal is not reversed; post the journal again instead' USING ERRCODE = 'SE007';
  END IF;
  v_roles := app.journal_source_reversal_roles(v_original.source_type);
  IF v_roles IS NULL OR NOT (v_role = ANY (v_roles)) THEN
    -- Someone who cannot read the ledger learns nothing about what is in it.
    IF v_role IN ('owner', 'accountant', 'auditor') THEN
      RAISE EXCEPTION 'this role cannot reverse that kind of journal' USING ERRCODE = 'insufficient_privilege';
    END IF;
    RAISE EXCEPTION 'no such journal in this company' USING ERRCODE = 'SE006';
  END IF;
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  IF EXISTS (SELECT 1 FROM public.journals j WHERE j.tenant_id = v_tenant AND j.reverses_journal_id = p_journal_id) THEN
    RAISE EXCEPTION 'that journal has already been reversed' USING ERRCODE = 'SE008';
  END IF;
  IF p_date IS NULL OR p_date < v_original.journal_date THEN
    RAISE EXCEPTION 'a reversal is dated on or after the journal it reverses' USING ERRCODE = 'SE009';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);

  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, reverses_journal_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, 'reversal', p_journal_id, p_journal_id, NULL, nullif(btrim(p_memo), ''), v_original.branch_id, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
    SELECT l.tenant_id, v_journal, l.line_no, l.account_id, l.credit, l.debit, l.description, l.customer_id, l.supplier_id
    FROM public.journal_lines l
    WHERE l.tenant_id = v_tenant AND l.journal_id = p_journal_id;
  SELECT count(*), sum(l.debit) INTO v_lines, v_total
    FROM public.journal_lines l WHERE l.tenant_id = v_tenant AND l.journal_id = v_journal;

  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.reverse', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'reverses', p_journal_id, 'source', v_original.source_type,
        'reversesNumber', v_original.document_number, 'lines', v_lines, 'total', v_total::text));
  RETURN v_journal;
END $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.cancel_delivery(p_document uuid, p_date date, p_reason text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.sales_documents%ROWTYPE;
  v_move record;
  v_original uuid;
  v_reversal uuid;
  v_total numeric;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'sales_manager', 'salesperson', 'warehouse_manager') THEN
    RAISE EXCEPTION 'this role cannot cancel a delivery note' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.* INTO v_doc FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = p_document AND d.kind = 'delivery'
    FOR UPDATE;
  IF NOT FOUND
     OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope)))
     OR (v_role = 'salesperson' AND v_doc.created_by <> v_user AND v_doc.salesperson_id IS DISTINCT FROM v_user) THEN
    RAISE EXCEPTION 'no such delivery note in this company' USING ERRCODE = 'SE063';
  END IF;
  IF v_doc.status <> 'submitted' THEN
    RAISE EXCEPTION 'only a posted delivery note is cancelled' USING ERRCODE = 'SE050';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.document_date THEN
    RAISE EXCEPTION 'a delivery note is cancelled on or after its own date' USING ERRCODE = 'SE009';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);

  SET CONSTRAINTS public.sales_documents_posted DEFERRED;
  -- Cancelled first: the document's own guard asks for the reason and writes the audit row.
  UPDATE public.sales_documents d SET status = 'cancelled', cancelled_by = v_user, cancel_reason = p_reason, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;

  FOR v_move IN
    SELECT m.id, m.item_id, m.warehouse_id, m.quantity, m.value, m.source_line_id
    FROM public.stock_moves m
    WHERE m.tenant_id = v_tenant AND m.source_type = 'delivery_note' AND m.source_id = v_doc.id AND m.reverses_move_id IS NULL
    ORDER BY m.item_id, m.created_at, m.id
  LOOP
    PERFORM app.move_stock(v_tenant, v_user, v_move.item_id, v_move.warehouse_id, p_date, -v_move.quantity, -v_move.value, 'delivery_note', v_doc.id, v_move.source_line_id, v_move.id);
  END LOOP;

  SELECT j.id INTO v_original FROM public.journals j WHERE j.tenant_id = v_tenant AND j.source_type = 'delivery_note' AND j.source_id = v_doc.id;
  IF v_original IS NOT NULL THEN
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, reverses_journal_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, p_date, 'reversal', v_original, v_original, NULL, left('Delivery note ' || v_doc.number || ' cancelled: ' || btrim(p_reason), 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_reversal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
      SELECT l.tenant_id, v_reversal, l.line_no, l.account_id, l.credit, l.debit, l.description, l.customer_id, l.supplier_id
      FROM public.journal_lines l
      WHERE l.tenant_id = v_tenant AND l.journal_id = v_original;
    SELECT sum(l.debit) INTO v_total FROM public.journal_lines l WHERE l.tenant_id = v_tenant AND l.journal_id = v_reversal;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.reverse', 'journal', v_reversal,
        jsonb_build_object('date', p_date, 'reverses', v_original, 'source', 'delivery_note', 'reversesNumber', v_doc.number, 'lines', 2, 'total', v_total::text));
  END IF;
  RETURN v_reversal;
END $$;
